add_filter( 'woocommerce_products_admin_list_table_filters', 'perfectpixel_featured_filter_register' );
add_filter( 'request', 'perfectpixel_featured_filter_query' );

function perfectpixel_featured_filter_register( $filters ) {
	$filters['perfectpixel_featured'] = 'perfectpixel_featured_filter_select';
	return $filters;
}

function perfectpixel_featured_filter_select() {
	$current = isset( $_GET['perfectpixel_featured'] ) ? sanitize_key( $_GET['perfectpixel_featured'] ) : '';
	echo '<select name="perfectpixel_featured">';
	foreach ( array( '' => 'Όλα (προβολή)', 'yes' => 'Προβεβλημένα', 'no' => 'Μη προβεβλημένα' ) as $value => $label ) {
		printf( '<option value="%s"%s>%s</option>', esc_attr( $value ), selected( $current, $value, false ), esc_html( $label ) );
	}
	echo '</select>';
}

function perfectpixel_featured_filter_query( $vars ) {
	global $typenow;
	if ( ! is_admin() || 'product' !== $typenow || empty( $_GET['perfectpixel_featured'] ) ) {
		return $vars;
	}
	$vars['tax_query'][] = array(
		'taxonomy' => 'product_visibility',
		'field'    => 'name',
		'terms'    => array( 'featured' ),
		'operator' => 'yes' === $_GET['perfectpixel_featured'] ? 'IN' : 'NOT IN',
	);
	return $vars;
}
